def assign_first_configured_shift(apps, schema_editor):
	FuelBooking = apps.get_model("ledger", "FuelBooking")
	Site = apps.get_model("ledger", "Site")
	database = schema_editor.connection.alias
	shift_by_site = {
		site.pk: "Morning" if site.shift_count == 3 else "Day"
		for site in Site.objects.using(database).only("pk", "shift_count")
	}
	for booking in FuelBooking.objects.using(database).all().iterator():
		FuelBooking.objects.using(database).filter(pk=booking.pk).update(
			shift_label=shift_by_site.get(booking.site_id, "Day")
		)

def mark_hq_configuration_events(apps, schema_editor):
    SiteAuditEvent = apps.get_model("ledger", "SiteAuditEvent")
    UserProfile = apps.get_model("ledger", "UserProfile")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    database = schema_editor.connection.alias
    hq_categories = [
        "Site",
        "Tank",
        "Nozzle",
        "Speed Point",
        "Manual Shop Point",
        "Cash Up Additional",
    ]
    SiteAuditEvent.objects.using(database).filter(category__in=hq_categories).update(origin="HQ")
    for event in SiteAuditEvent.objects.using(database).filter(category__in=["Site user", "Site group"]).iterator():
        if not event.actor_id:
            continue
        is_superuser = User.objects.using(database).filter(pk=event.actor_id).values_list("is_superuser", flat=True).first()
        role = UserProfile.objects.using(database).filter(user_id=event.actor_id).values_list("role", flat=True).first()
        if is_superuser or role == "HQ":
            SiteAuditEvent.objects.using(database).filter(pk=event.pk).update(origin="HQ")

def create_django_groups(apps, schema_editor):
    SiteGroup = apps.get_model('ledger', 'SiteGroup')
    Group = apps.get_model('auth', 'Group')
    for site_group in SiteGroup.objects.select_related('site').iterator():
        django_group, _ = Group.objects.get_or_create(name=f'Site {site_group.site_id} - {site_group.name}')
        site_group.django_group_id = django_group.pk
        site_group.save(update_fields=['django_group'])
        django_group.user_set.add(*site_group.users.all())

def noop_reverse(apps, schema_editor):
    pass


